-  T operator()(const volatile T* p) const { T data; __atomic_load(const_cast<T*>(p), &data, __ATOMIC_ACQUIRE); return data; }
+  T operator()(const volatile T* p) const {
+    T data;
+    __atomic_load(const_cast<T*>(p), &data, __ATOMIC_RELAXED);
+    OrderAccess::acquire();
+    return data;
+  }
@@ -221,1 +272,4 @@
